public int KthSmallest(int[][] matrix, int k)
{
    int n = matrix.Length;
    int lo = matrix[0][0], hi = matrix[n - 1][n - 1];
    while (lo < hi)
    {
        int mid = lo + (hi - lo) / 2;
        if (CountLessEqual(matrix, mid) >= k) hi = mid;
        else lo = mid + 1;
    }
    return lo;
}

private int CountLessEqual(int[][] matrix, int target)
{
    int n = matrix.Length, count = 0, row = 0, col = n - 1;
    while (row < n && col >= 0)
    {
        if (matrix[row][col] <= target) { count += col + 1; row++; }
        else col--;
    }
    return count;
}

public int KthSmallest(int[][] matrix, int k)
{
    var maxHeap = new PriorityQueue<int, int>();
    foreach (var row in matrix)
        foreach (int v in row)
        {
            maxHeap.Enqueue(v, -v);              // simulate max-heap
            if (maxHeap.Count > k) maxHeap.Dequeue(); // drop largest
        }
    return maxHeap.Peek();
}
